draw((1,sqrt(3))--(1,-sqrt(3))--(-1,-sqrt(3))--(-1,sqrt(3))--cycle);

dot((1,sqrt(3)));
dot((1,-sqrt(3)));
dot((-1,sqrt(3)));
dot((-1,-sqrt(3)));

